<?php echo form_open(get_uri('warehouses/products/save'),['id'=>'warehouse-product-form']);echo csrf_field(); ?><div class="modal-header"><h5 class="modal-title"><?php echo empty($row->id)?'Nuevo producto de almacén':'Editar producto de almacén'; ?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="id" value="<?php echo(int)($row->id??0); ?>"><label>Nombre</label><input class="form-control" name="name" required value="<?php echo esc($row->name??''); ?>"><label>Descripción</label><textarea class="form-control" name="description"><?php echo esc($row->description??''); ?></textarea><div class="row"><div class="col-md-4"><label>Código interno</label><input class="form-control text-uppercase" name="internal_code" required value="<?php echo esc($row->internal_code??''); ?>"></div><div class="col-md-4"><label>Código de barras</label><input class="form-control" name="barcode" value="<?php echo esc($row->barcode??''); ?>"></div><div class="col-md-4"><label>Unidad de control</label><input class="form-control" name="control_unit" placeholder="PIEZA, PAR, CAJA..." required value="<?php echo esc($row->control_unit??''); ?>"></div></div><div class="row"><?php foreach(['category'=>'Categoría','brand'=>'Marca','model'=>'Modelo','variant'=>'Variante','size'=>'Talla','color'=>'Color']as$f=>$l): ?><div class="col-md-4"><label><?php echo$l; ?></label><input class="form-control" name="<?php echo$f; ?>" value="<?php echo esc($row->$f??''); ?>"></div><?php endforeach; ?></div><label>Notas</label><textarea class="form-control" name="notes"><?php echo esc($row->notes??''); ?></textarea><label>Estado</label><?php echo form_dropdown('status',['active'=>'Activo','inactive'=>'Inactivo'],$row->status??'active',"class='form-control'"); ?></div><div class="modal-footer"><button class="btn btn-default" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div><?php echo form_close(); ?><script>$('#warehouse-product-form').appForm({onSuccess:function(){location.reload();}});</script>
